export type ParsedFundAgreementInstruction<
  TProgram extends string = typeof PACTUM_ESCROW_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    clientAuthority: TAccountMetas[0];
    escrowConfig: TAccountMetas[1];
    globalConfig: TAccountMetas[2];
    client: TAccountMetas[3];
    agreement: TAccountMetas[4];
    escrowVault: TAccountMetas[5];
    clientTokenAccount: TAccountMetas[6];
    usdcMint: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
  };
  data: FundAgreementInstructionData;
};

export function parseFundAgreementInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedFundAgreementInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      clientAuthority: getNextAccount(),
      escrowConfig: getNextAccount(),
      globalConfig: getNextAccount(),
      client: getNextAccount(),
      agreement: getNextAccount(),
      escrowVault: getNextAccount(),
      clientTokenAccount: getNextAccount(),
      usdcMint: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getFundAgreementInstructionDataDecoder().decode(instruction.data),
  };
}
